contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address burner, address account, uint256 tokenId, uint256 amount) public {
        require(burner != address(0));

        bool flag = c.allowedBurningAddresses(burner); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(account, tokenId, amount); if (__ESBMC_reverted()) return;
        reverted = false;
        assert(reverted && !flag);
    }

    receive() external payable {}
}

