    function _run(address burner, address account, uint256 tokenId, uint256 amount) internal {
        vm.assume(burner != address(0));
        bool flag;
        try c.allowedBurningAddresses(burner) returns (bool __r) { flag = __r; } catch { return; }
        bool reverted;
        try c.burn(account, tokenId, amount) {} catch { return; }
        reverted = false;
        assertTrue(reverted && !flag);
    }

